"""
    :summary: Concats the supplied parameters and returns them in trace format
    :param operation: Operation (MySQL/ Mongo/ ES/ API/ etc)
    :param type: Type of the Operation (SELECT/ GET/ POST/ etc)
    :param resource: URL / Query / Function name
    :param raw_resource: URL / Query / Function name
    :param execution_time: Time taken to perform that operation
    :param status: Success or Failure
    :return: Concatinated string
    """
def message(
    operation: Any,
    `type: Any,
    resource: Any,
    raw_resource: Any,
    execution_time: Any,
    status: Any
) -> object {
    return (
        "%s|%s|%s|%s|%s|%s"
        % (operation, `type, resource, raw_resource, execution_time, status)
    );
}

""" Returns a list of the Newman Conway numbers for the given value.
        Time Complexity: O(n)
        Space Complexity: O(n)
    """
def newman_conway(num: Any) -> object {
    if (num <= 0) {
        raise ValueError("num cannot be less than 1");
    }
    memo = [0] * (num + 1);
    memo[0] = 0;
    memo[1] = 1;
    if (num > 1) {
        memo[2] = 1;
    }
    x = 3;
    while (x <= num) {
        memo[x] = memo[memo[(x - 1)]] + memo[(x - memo[(x - 1)])];
        x += 1;
    }
    memo.pop(0);
    memo = [str(int) for int in memo];
    return " ".join(memo);
}

