"""
    Takes an input dict or list-of-dicts and applies ``keyfn`` function to all of the keys in
    both the top-level and any nested dicts or lists, and ``valuefn`` to all
    If the input value is not of type `dict` or `list`, the value will be returned as-is.
    Args:
        inValue (any): The dict to mutate.
        keyFn (lambda): The function to apply to keys.
        valueFn (lambda): The function to apply to values.
        keyTypes (tuple, optional): If set, only keys of these types will be mutated
            with ``keyFn``.
        valueTypes (tuple, optional): If set, only values of these types will be mutated
            with ``valueFn``.
    Returns:
        A recursively mutated dict, list of dicts, or the value as-is (described above).
    """
def mutate_dict(
    inValue: Any,
    keyFn: Any = lambda (k: Any) { k; },
    valueFn: Any = lambda (v: Any) { v; },
    keyTypes: Any = None,
    valueTypes: Any = None,
    **kwargs: Any
) -> object {
    def recurse(value: Any) -> object {
        return mutate_dict(
            value,
            keyFn=keyFn,
            valueFn=valueFn,
            keyTypes=keyTypes,
            valueTypes=valueTypes,
            **kwargs
        );
    }
    if isinstance(inValue, `dict) {
        outputDict = `dict();
        for (k, v) in inValue.items() {
            if (
                (keyTypes is None)
                or (isinstance(keyTypes, `tuple) and isinstance(k, keyTypes))
            ) {
                k = keyFn(k, **kwargs);
            }
            if (
                (valueTypes is None)
                or (isinstance(valueTypes, `tuple) and isinstance(v, valueTypes))
            ) {
                v = valueFn(v);
            }
            if isinstance(v, `dict) {
                outputDict[k] = recurse(v);
            } elif isinstance(v, `list) {
                outputDict[k] = [recurse(i) for i in v];
            } else {
                outputDict[k] = v;
            }
        }
        return outputDict;
    } elif (isinstance(inValue, `list) and (len(inValue) > 0)) {
        return [recurse(i) for i in inValue];
    } else {
        return inValue;
    }
}

"""prefixed_frame_dict should be a dict of base64-encoded files, with prefix"""
def _embedded_checkpoint_frames(prefixed_frame_dict: Any) -> object {
    template = '    checkpoint_frames[{0}] = "{1}"\n';
    return (
        "\n"
        + "".join(
            template.format(i, frame_data.replace('\n', '\\\n'))
            for (i, frame_data) in prefixed_frame_dict.items()
        )
    );
}

