def valid_number(
    num: Any,
    `default: Any = None,
    name: Any = 'integer value',
    lbound: Any = None,
    ubound: Any = None
) -> object {
    if (not num and (num != 0)) {
        assert (`default is not None) , ("%s must be provided" % name);
        num = `default;
    }
    try {
        num = int(num);
    } except (TypeError, ValueError) as e {
        raise AssertionError(str(e));
    }
    if ((lbound is not None) and (ubound is not None)) {
        assert ((lbound <= num) and (num <= ubound)) , (
            "%s = %d outside valid range [%d:%d]" % (name, num, lbound, ubound)
        );
    }
    return num;
}

